void StepSequencerComponent::applyPatternSet(const PatternSet& patternSet)
{
    juce::Logger::writeToLog("[StepSequencer] === APPLY PATTERN SET ===");
    // ... updates genre, resizes grid, then:
    for (int row = 0; row < numRows; ++row) {
        DrumCategory rowCat = getRowCategory(row);
        // First try subcategory match by name
        // Then try base category match
        auto it = patternSet.patterns.find(rowCat);
        if (it != patternSet.patterns.end() && !it->second.steps.empty()) {
            // Apply steps
            for (int step = 0; step < numSteps; ++step) {
                grid_[row][step] = pattern.steps[step];
            }
        }
    }
    regenerateMidiFile();
    repaint();
    if (onPatternChanged) onPatternChanged();
}

