void StepSequencerComponent::addTrackRow(const DrumTrack& track)
{
    const int steps = grid_.empty() ? cfg_.steps : static_cast<int>(grid_[0].size());
    std::vector<uint8_t> row(steps, 0);
    int copySteps = std::min(16, steps);
    for (int s = 0; s < copySteps; ++s) {
        row[s] = track.steps[s];
    }
    grid_.push_back(row);
    rowFiles_.push_back(juce::File());
    rowLocked_.push_back(false);
    rowSoloed_.push_back(false);
    rowPatternRole_.push_back(PatternLibrary::categoryToRole(track.category));
    rowCategory_.push_back(track.category);
    rowMidiNote_.push_back(track.midiNote);
    stepRollData_.push_back(std::vector<StepData>(steps));
    cfg_.rowNames.add(track.name);
    cfg_.rows = static_cast<int>(grid_.size());
    // Creates [G] button for new row
    auto btn = std::make_unique<ChannelGenerateButton>(...)
    addAndMakeVisible(*btn);
    channelGenButtons_.push_back(std::move(btn));
    regenerateMidiFile();
    resized();
    repaint();
}

